    return `${e.name} ${e.id} ${e.taskId ?? ''} ${this.taskMap.get(e.taskId)?.label ?? ''} ${e.blockId ?? ''} ${lane?.coreId} ${lane?.pipe} ${lane?.engine} ${kernel?.label} ${JSON.stringify(e.args ?? {})}`.toLowerCase().includes(this.query.toLowerCase());
